import { defineConfig, loadEnv, UserConfig } from 'vite';
import react from '@vitejs/plugin-react';
import basicSsl from '@vitejs/plugin-basic-ssl';
import tsconfigPaths from 'vite-tsconfig-paths';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Long-lived trusted dev cert generated by `npm run certs:generate` (scripts/generate-dev-cert.ps1).
// Works on any port. Falls back to basicSsl's throwaway cert when absent.
const pfxPath = path.join(path.dirname(fileURLToPath(import.meta.url)), 'certs', 'localhost.pfx');
const hasDevCert = fs.existsSync(pfxPath);
const devHttps = hasDevCert
	? { pfx: fs.readFileSync(pfxPath), passphrase: 'fake-passphrase' }
	: undefined;

// Base configuration shared across all environments
const baseConfig: UserConfig = {
	plugins: [react(), ...(process.env.NO_SSL || hasDevCert ? [] : [basicSsl()]), tsconfigPaths()],
};

// Development configuration
const developmentConfig = (baseUrl: string): UserConfig => ({
	...baseConfig,
	server: {
		host: true,
		...(process.env.NO_SSL ? {} : { https: devHttps }),
		// Proxy API requests to backend in development
		// This enables same-origin cookie handling
		proxy: {
			'/assets': {
				target: baseUrl,
				changeOrigin: true,
				secure: false,
				cookieDomainRewrite: 'localhost',
			},
			'/api': {
				target: baseUrl,
				changeOrigin: true,
				secure: false,
				cookieDomainRewrite: 'localhost',
			},
			'/account': {
				target: baseUrl,
				changeOrigin: true,
				secure: false,
				cookieDomainRewrite: 'localhost',
			},
			'/signalr': {
				target: baseUrl,
				changeOrigin: true,
				secure: false,
				cookieDomainRewrite: 'localhost',
				ws: true,
			},
		},
	},
});

// Production configuration
const productionConfig: UserConfig = {
	...baseConfig,
	build: {
		outDir: 'dist',
		sourcemap: false,
		minify: true,
	},
};

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => {
	const env = loadEnv(mode, process.cwd(), '');
	const isDevelopment = env.VITE_NODE_ENV === 'development';
	const baseUrl = env.VITE_BASE_URL;

	if (!baseUrl) {
		throw new Error('VITE_BASE_URL is not defined in environment variables');
	}

	if (isDevelopment) {
		return developmentConfig(baseUrl);
	}

	return productionConfig;
});
